CREATE TABLE IF NOT EXISTS drawing_structure_review_cases (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,structure_version_id TEXT NOT NULL,legend_row_id TEXT NOT NULL,parent_case_id TEXT,case_version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'Needs Review',original_snapshot TEXT NOT NULL,current_snapshot TEXT NOT NULL,adjustments TEXT NOT NULL DEFAULT '[]',reviewed_by TEXT,reviewed_at TEXT,review_reason TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(structure_version_id) REFERENCES drawing_structure_versions(id),FOREIGN KEY(legend_row_id) REFERENCES drawing_structure_legend_rows(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_structure_review_case_row_idx ON drawing_structure_review_cases(structure_version_id,legend_row_id);
CREATE INDEX IF NOT EXISTS drawing_structure_review_case_status_idx ON drawing_structure_review_cases(document_id,status,updated_at);
CREATE TABLE IF NOT EXISTS drawing_structure_review_events (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,structure_version_id TEXT NOT NULL,review_case_id TEXT NOT NULL,action TEXT NOT NULL,previous_snapshot TEXT NOT NULL,new_snapshot TEXT NOT NULL,reason TEXT NOT NULL,actor_user_id TEXT NOT NULL,actor_permission TEXT NOT NULL,request_id TEXT NOT NULL,case_version INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(review_case_id) REFERENCES drawing_structure_review_cases(id));
CREATE INDEX IF NOT EXISTS drawing_structure_review_event_idx ON drawing_structure_review_events(review_case_id,created_at);
CREATE TABLE IF NOT EXISTS drawing_structure_approved_versions (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,source_structure_version_id TEXT NOT NULL,version_number INTEGER NOT NULL,input_fingerprint TEXT NOT NULL,output_fingerprint TEXT NOT NULL,status TEXT NOT NULL,approved_row_count INTEGER NOT NULL,excluded_row_count INTEGER NOT NULL,created_by TEXT NOT NULL,reason TEXT NOT NULL,superseded_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(source_structure_version_id) REFERENCES drawing_structure_versions(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_structure_approved_version_idx ON drawing_structure_approved_versions(document_id,version_number);
CREATE INDEX IF NOT EXISTS drawing_structure_approved_current_idx ON drawing_structure_approved_versions(document_id,superseded_at);
CREATE TABLE IF NOT EXISTS drawing_structure_approved_rows (id TEXT PRIMARY KEY,approved_version_id TEXT NOT NULL,review_case_id TEXT NOT NULL,source_legend_row_id TEXT NOT NULL,source_page INTEGER NOT NULL,source_row INTEGER NOT NULL,symbol_geometry TEXT NOT NULL,abbreviation TEXT,description TEXT,notes TEXT,bounding_box TEXT,structural_confidence INTEGER NOT NULL,review_actor_id TEXT NOT NULL,review_reason TEXT NOT NULL,source_snapshot TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(approved_version_id) REFERENCES drawing_structure_approved_versions(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_structure_approved_row_idx ON drawing_structure_approved_rows(approved_version_id,review_case_id,source_row);
CREATE TABLE IF NOT EXISTS drawing_structure_approved_audit_events (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,approved_version_id TEXT NOT NULL,action TEXT NOT NULL,previous_value TEXT,new_value TEXT NOT NULL,reason TEXT NOT NULL,actor_user_id TEXT NOT NULL,request_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(approved_version_id) REFERENCES drawing_structure_approved_versions(id));
CREATE INDEX IF NOT EXISTS drawing_structure_approved_audit_idx ON drawing_structure_approved_audit_events(document_id,created_at);
